package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * SPARQL treats {@code sameTerm} and the type tests ({@code isIRI}, {@code isLiteral}, ...) over an unbound argument as
 * a type error, and {@code NOT(error)} stays an error, so FILTER must drop the row. A null-extended OPTIONAL row must
 * therefore never survive {@code FILTER(!isIRI(?opt))}: folding the unbound operand to FALSE instead of ERROR lets the
 * enclosing NOT flip it to TRUE and keep rows the generic engine rejects.
 */
public class LmdbNativeNotOverUnboundFilterTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String JANINO_FLAG = "rdf4j.lmdb.janinoCodegen.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		// pin the id-specialized codegen tier off so the interpreted expression tier evaluates the filter
		System.setProperty(JANINO_FLAG, "false");
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI name = vf.createIRI(EX, "name");
			IRI link = vf.createIRI(EX, "link");
			conn.begin();
			// s1 links to the target IRI, s2 links to a literal, s3 has no link (null-extended OPTIONAL row)
			IRI s1 = vf.createIRI(EX, "s1");
			IRI s2 = vf.createIRI(EX, "s2");
			IRI s3 = vf.createIRI(EX, "s3");
			conn.add(s1, name, vf.createLiteral("s1"));
			conn.add(s1, link, vf.createIRI(EX, "target"));
			conn.add(s2, name, vf.createLiteral("s2"));
			conn.add(s2, link, vf.createLiteral("literal"));
			conn.add(s3, name, vf.createLiteral("s3"));
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		System.clearProperty(NATIVE_FLAG);
		System.clearProperty(JANINO_FLAG);
		repository.shutDown();
	}

	@Test
	public void notIsIriOverNullExtendedOptionalRowMatchesGeneric() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s ?opt WHERE { ?s ex:name ?n . OPTIONAL { ?s ex:link ?opt } FILTER(!isIRI(?opt)) }";
		List<String> generic = genericRows(query);
		// s1 has an IRI link (rejected), s2 a literal link (kept), s3 is null-extended: isIRI errors, NOT keeps the
		// error, FILTER drops the row
		assertThat(generic).containsExactly("opt=\"literal\",s=" + iri("s2"));
		assertThat(rows(query)).isEqualTo(generic);
	}

	@Test
	public void notSameTermOverNullExtendedOptionalRowMatchesGeneric() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s ?opt WHERE { ?s ex:name ?n . OPTIONAL { ?s ex:link ?opt } "
				+ "FILTER(!sameTerm(?opt, ex:target)) }";
		List<String> generic = genericRows(query);
		// s1 matches the target (rejected), s2 differs (kept), s3 is null-extended: sameTerm errors and the row drops
		assertThat(generic).containsExactly("opt=\"literal\",s=" + iri("s2"));
		assertThat(rows(query)).isEqualTo(generic);
	}

	@Test
	public void notIsLiteralOverNullExtendedOptionalRowMatchesGeneric() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s ?opt WHERE { ?s ex:name ?n . OPTIONAL { ?s ex:link ?opt } FILTER(!isLiteral(?opt)) }";
		List<String> generic = genericRows(query);
		assertThat(generic).containsExactly("opt=" + iri("target") + ",s=" + iri("s1"));
		assertThat(rows(query)).isEqualTo(generic);
	}

	private static String iri(String localName) {
		return EX + localName;
	}

	private List<String> genericRows(String query) {
		System.setProperty(NATIVE_FLAG, "false");
		try {
			return rows(query);
		} finally {
			System.clearProperty(NATIVE_FLAG);
		}
	}

	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(QueryLanguage.SPARQL, query).evaluate())
					.stream()
					.map(LmdbNativeNotOverUnboundFilterTest::render)
					.sorted()
					.collect(Collectors.toList());
		}
	}

	private static String render(BindingSet bindings) {
		return bindings.getBindingNames()
				.stream()
				.sorted()
				.map(name -> name + "=" + bindings.getValue(name))
				.collect(Collectors.joining(","));
	}
}
